```toml
# Cargo.toml
dialoguer = "0.11"
```

### Confirm (yes/no)

```rust
use dialoguer::{theme::ColorfulTheme, Confirm};

let theme = ColorfulTheme::default();
let enabled = Confirm::with_theme(&theme)
    .with_prompt("Enable feature X?")
    .default(false)
    .interact()
    .unwrap_or(false);
```

### Select (single choice from list)

```rust
use dialoguer::{theme::ColorfulTheme, Select};

let theme = ColorfulTheme::default();
let options = ["Option A", "Option B", "Option C"];
let choice = Select::with_theme(&theme)
    .with_prompt("Select an option")
    .items(&options)
    .default(0)
    .interact()
    .unwrap_or(0);
```

### MultiSelect (multiple choices with space to toggle)

```rust
use dialoguer::{theme::ColorfulTheme, MultiSelect};

let theme = ColorfulTheme::default();
let items = ["Item 1", "Item 2", "Item 3"];
let selections = MultiSelect::with_theme(&theme)
    .with_prompt("Select items (Space to toggle, Enter to confirm)")
    .items(&items)
    .interact()
    .unwrap_or_default();
// selections is Vec<usize> of selected indices
```

### Input (free text)

```rust
use dialoguer::{theme::ColorfulTheme, Input};

let name: String = Input::with_theme(&theme)
    .with_prompt("Enter your name")
    .interact_text()
    .unwrap_or_default();
